using System.Security.AccessControl;using System.Security.Principal;using System.Text.Json;using RouterStudio.Core.Contracts;
namespace RouterStudio.Core.Services;
public sealed record ActivityRecord(DateTimeOffset AtUtc,string Action,bool Ok,string SnapshotDigest,ProbeResult? Probe=null);
public sealed class HistoryStore {
 private readonly string root;private readonly Func<DateTimeOffset> clock;private readonly object gate=new();
 public string? Notice {get;private set;}
 public HistoryStore(string directory,Func<DateTimeOffset>? clock=null){root=Path.GetFullPath(directory);this.clock=clock??(()=>DateTimeOffset.UtcNow);}
 private void Prepare(){Directory.CreateDirectory(root);if((File.GetAttributes(root)&FileAttributes.ReparsePoint)!=0)throw new IOException();var security=new DirectorySecurity();security.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WindowsIdentity.GetCurrent().User!,new SecurityIdentifier(WellKnownSidType.LocalSystemSid,null)})security.AddAccessRule(new FileSystemAccessRule(sid,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));new DirectoryInfo(root).SetAccessControl(security);}
 private string PathFor(string suffix="")=>Path.Combine(root,"history.json"+suffix);
 private List<ActivityRecord> Load(string path){if(!File.Exists(path))return [];if(new FileInfo(path).Length>512*1024||(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException();return JsonSerializer.Deserialize<List<ActivityRecord>>(File.ReadAllBytes(path),StudioJson.Options)??throw new JsonException();}
 private bool Valid(ActivityRecord? row){try{return row is not null&&row.AtUtc!=default&&row.AtUtc<=clock().AddMinutes(5)&&ProbeCodec.Digest(row.SnapshotDigest)&&row.Action is "probe" or "official" or "router" or "start" or "stop" or "repair" or "restore" or "save-key" or "install"&&(row.Probe is null||ProbeCodec.Validate(row.Probe) is not null);}catch(JsonException){return false;}}
 private List<ActivityRecord> Retain(IEnumerable<ActivityRecord> rows)=>rows.Where(row=>Valid(row)&&row.AtUtc>=clock().AddDays(-30)).OrderByDescending(row=>row.AtUtc).Take(200).ToList();
 private List<ActivityRecord> ReadCore(){try{return Retain(Load(PathFor()));}catch(Exception ex) when(ex is IOException or UnauthorizedAccessException or JsonException){Notice="History could not be read completely. Other controls remain available.";try{return Retain(Load(PathFor(".previous")));}catch(Exception error) when(error is IOException or UnauthorizedAccessException or JsonException){return [];}}}
 public IReadOnlyList<ActivityRecord> Read(){lock(gate)return ReadCore();}
 private void Save(List<ActivityRecord> rows){Prepare();var path=PathFor();foreach(var target in new[]{path,PathFor(".tmp"),PathFor(".previous")})if(File.Exists(target)&&(File.GetAttributes(target)&FileAttributes.ReparsePoint)!=0)throw new IOException();var bytes=JsonSerializer.SerializeToUtf8Bytes(Retain(rows),StudioJson.Options);File.WriteAllBytes(PathFor(".tmp"),bytes);if(File.Exists(path)){try{File.WriteAllBytes(PathFor(".previous"),JsonSerializer.SerializeToUtf8Bytes(Retain(Load(path)),StudioJson.Options));}catch(JsonException){}}File.Move(PathFor(".tmp"),path,true);}
 private void Append(ActivityRecord row){lock(gate){if(!Valid(row)){Notice="An invalid history record was discarded.";return;}try{var rows=ReadCore();rows.Insert(0,row);Save(rows);}catch(Exception ex) when(ex is IOException or UnauthorizedAccessException){Notice="History could not be saved. The operation result remains available in this session.";}}}
 public void AppendProbe(ProbeResult result)=>Append(new(result.CompletedAtUtc,"probe",result.Outcome==ProbeOutcome.Passed,result.SnapshotDigest,result));
 public void AppendAction(string action,bool ok,string digest)=>Append(new(clock(),action,ok,digest));
 public void Clear(){lock(gate){try{Save([]);File.Delete(PathFor(".previous"));Notice=null;}catch(Exception ex) when(ex is IOException or UnauthorizedAccessException){Notice="History could not be cleared.";}}}
 private static string VersionText(string value)=>Version.TryParse(value.TrimStart('v'),out var version)?version.ToString():"Unknown";
 public string Export(StudioSnapshot? snapshot){lock(gate)return JsonSerializer.Serialize(new{schemaVersion=1,scope="Local management and explicit direct-gateway checks; authentication and quota remain unverified.",runtimeVersions=new{node=VersionText(snapshot?.RuntimeVersions.Node??""),powershell=VersionText(snapshot?.RuntimeVersions.PowerShell??"")},activities=ReadCore().Select(row=>new{row.AtUtc,row.Action,row.Ok,row.Probe,stale=snapshot is null||row.SnapshotDigest!=snapshot.SnapshotDigest})},StudioJson.Options);}
}
